import { useCallback, useEffect, useRef, useState } from "react";
import { doc, getDoc, updateDoc } from "firebase/firestore";
import { db } from "./firebase";
import { aiStatus, fetchWorld } from "./aiApi";
import { bookSummary, useReadingProgress } from "./readingProgress";

// Loads a book and its story world. The world is generated by the AI once,
// then saved on the book in Firestore so every reader gets the same map.
// The reader's chapter is their own (see readingProgress.js).
// `canBuild(book)` can veto generating a world for books that don't need one (status "unavailable").
export function useBookWorld(id, canBuild = () => true) {
  const [item, setItem] = useState(null);
  const [world, setWorld] = useState(null);
  const [status, setStatus] = useState("loading"); // loading | building | ready | unavailable | error
  const [error, setError] = useState("");
  const canBuildRef = useRef(canBuild);
  canBuildRef.current = canBuild;
  const reading = useReadingProgress(id);

  useEffect(() => {
    let cancelled = false;

    const load = async () => {
      try {
        const snap = await getDoc(doc(db, "item", id));
        if (!snap.exists()) throw new Error("Book not found.");
        const data = { id, ...snap.data() };
        if (cancelled) return;
        setItem(data);

        if (!canBuildRef.current(data)) {
          setStatus("unavailable");
          return;
        }

        // Maps made before chapters existed are rebuilt.
        if (data.world?.chapters?.length) {
          setWorld(data.world);
          setStatus("ready");
          return;
        }

        const ai = await aiStatus();
        if (ai === "offline") throw new Error("The AI server isn't running. Start it with: npm.cmd run server");
        if (ai === "no-key") throw new Error("The AI isn't set up yet. Add your free Gemini API key to server/.env and restart the AI server.");

        setStatus("building");
        const generated = await fetchWorld(data);
        if (cancelled) return;
        setWorld(generated);
        setStatus("ready");
        updateDoc(doc(db, "item", id), { world: generated }).catch((err) =>
          console.error("Could not save the world map:", err)
        );
      } catch (err) {
        if (cancelled) return;
        setError(err.message);
        setStatus("error");
      }
    };

    load();
    return () => {
      cancelled = true;
    };
  }, [id]);

  const { save } = reading;
  const total = world?.chapters.length || 1;
  const saveProgress = useCallback(
    (chapter) => save({ chapter, progress: (chapter / total) * 100 }, bookSummary(item, total)),
    [save, total, item]
  );

  const chapter = world ? Math.min(reading.chapter, total) : reading.chapter;
  return { item, world, chapter, setChapter: reading.setChapter, saveProgress, status, error };
}
